function updateDebug(){const modes=['off','validation','fov','walkability','paths','occupancy','queue'];if(debugMode==='off'){$('debugBox').textContent='';return;}const v=E.validateMap(state.map),enemies=state.enemies;let text='DIAGNOSTICS · '+debugMode.toUpperCase()+'  [`] cycle\n';if(debugMode==='validation')text+='Seed '+state.config.seed+' / RNG '+state.rng+'\nConnected '+v.reachable+'/'+v.total+' · regions '+v.regions+'\nExit distance '+v.exitDistance+' · '+(v.valid?'VALID':'INVALID')+'\nState '+E.fingerprint(state);else if(debugMode==='fov')text+='Cyan: visible · slate: explored\nLOS blocks at stone & closed doors\nVisible enemies: '+visibleEnemies().length;else if(debugMode==='walkability')text+='Green: traversable · amber: closed door\nDoors are reachable in connectivity checks\nRegions '+v.regions+' · '+v.total+' walkable tiles';else if(debugMode==='occupancy')text+='Occupants: '+enemies.length+' enemies + player\nUnique positions: '+new Set(enemies.map(e=>E.key(e.x,e.y))).size+'/'+enemies.length+'\nWalls / collisions: '+(enemies.some(e=>!E.walk(state.map,e.x,e.y))?'INVALID':'clear');else if(debugMode==='queue')text+='Turn '+state.turn+' · '+(paused?'PAUSED':'awaiting input')+'\nLast queue: '+state.queue.join(' → ')+'\n'+enemies.slice(0,8).map(e=>'#'+e.id+' last acted T'+e.lastAct).join('\n');else text+=visibleEnemies().slice(0,6).map(e=>'#'+e.id+' '+e.intent+'\n  memory '+(e.memory?e.memory.x+','+e.memory.y+' ('+e.alert+'t)':'none')).join('\n')||'No visible AI. Hidden enemies remain hidden.';$('debugBox').textContent=text;}
