function tileFromPointer(event){const r=canvas.getBoundingClientRect();return{x:Math.floor((event.clientX-r.left-view.w/2)/view.cell+view.cx+.5),y:Math.floor((event.clientY-r.top-view.h/2)/view.cell+view.cy+.5)};}
