function wallTile(x,y,visible){const {x:sx,y:sy}=screen(x,y),c=view.cell,l=sx-c/2,t=sy-c/2,below=E.tile(state.map,x,y+1)>0,r=visualHash(x,y);ctx.save();ctx.globalAlpha=visible?1:.24;ctx.fillStyle='#161e15';ctx.fillRect(l,t,c,c);if(below){ctx.fillStyle='#293122';ctx.fillRect(l+1,t+c*.56,c-2,c*.46);ctx.fillStyle='#4f573a';ctx.fillRect(l+2,t+c*.55,c-4,c*.1);ctx.fillStyle='#1a2318';ctx.fillRect(l+c*.5,t+c*.62,2,c*.38);ctx.fillStyle='#8a946044';ctx.fillRect(l+3,t+c*.67,c*.34,2);ctx.fillStyle='#0c140ccc';ctx.fillRect(l,t+c*.95,c,3);}const stone=r>.5?'#3b4630':'#35402c';polygon([[l+1,t-4],[l+c-2,t-3],[l+c-1,t+c*.58],[l+2,t+c*.59]],stone,'#141e1280');ctx.fillStyle='#65704a60';ctx.fillRect(l+3,t-2,c-7,2);ctx.fillStyle='#1d2b18';ctx.fillRect(l+c*.51,t-2,2,c*.6);ctx.fillStyle='#222f1d';ctx.fillRect(l+1,t+c*.28,c-3,2);if((state.map.style==='ruins'||state.map.style==='cavern')&&r>.46){for(let i=0;i<5;i++){ctx.fillStyle=['#455b35','#526a3b','#69794a'][i%3];ctx.beginPath();ctx.ellipse(l+visualHash(x,y,i+12)*c,t+visualHash(x,y,i+42)*c*.5,c*.12,c*.06,i,0,Math.PI*2);ctx.fill();}if(r>.8){ctx.strokeStyle='#7b8b4d70';ctx.beginPath();ctx.moveTo(l+c*.2,t+c*.3);ctx.quadraticCurveTo(l+c*.6,t+c*.8,l+c*.3,t+c*1.2);ctx.stroke();}}ctx.restore();}
