function render(time){const s=state,m=s.map;camera();ctx.clearRect(0,0,view.w,view.h);ctx.fillStyle='#10160f';ctx.fillRect(0,0,view.w,view.h);const minX=Math.max(0,Math.floor(view.cx-view.w/view.cell/2)-1),maxX=Math.min(m.w-1,Math.ceil(view.cx+view.w/view.cell/2)+1),minY=Math.max(0,Math.floor(view.cy-view.h/view.cell/2)-1),maxY=Math.min(m.h-1,Math.ceil(view.cy+view.h/view.cell/2)+1);
 // Fine cartographic lattice remains in unexplored darkness without revealing terrain.
 ctx.strokeStyle='#4b5a3520';ctx.lineWidth=.5;for(let x=minX;x<=maxX;x++){let p=screen(x-.5,0);ctx.beginPath();ctx.moveTo(p.x,0);ctx.lineTo(p.x,view.h);ctx.stroke();}for(let y=minY;y<=maxY;y++){let p=screen(0,y-.5);ctx.beginPath();ctx.moveTo(0,p.y);ctx.lineTo(view.w,p.y);ctx.stroke();}
 for(let y=minY;y<=maxY;y++)for(let x=minX;x<=maxX;x++){let i=y*m.w+x;if(!s.explored[i])continue;if(m.tiles[i]>0)floorTile(x,y,s.visible[i]);}
 // The entry's faded compass rose is part of the generated room, not an image asset.
 if(s.explored[m.entry.y*m.w+m.entry.x]){const p=screen(m.entry.x,m.entry.y);ctx.save();ctx.strokeStyle='#bdbe7950';ctx.lineWidth=1;ctx.beginPath();ctx.arc(p.x,p.y,view.cell*1.18,0,Math.PI*2);ctx.stroke();ctx.strokeStyle='#aab27428';ctx.beginPath();ctx.arc(p.x,p.y,view.cell*1.35,0,Math.PI*2);ctx.stroke();for(let i=0;i<8;i++){let a=i*Math.PI/4;ctx.beginPath();ctx.moveTo(p.x+Math.cos(a)*view.cell*.9,p.y+Math.sin(a)*view.cell*.9);ctx.lineTo(p.x+Math.cos(a)*view.cell*1.32,p.y+Math.sin(a)*view.cell*1.32);ctx.stroke();}ctx.restore();}
 for(let y=minY;y<=maxY;y++)for(let x=minX;x<=maxX;x++){let i=y*m.w+x;if(!s.explored[i])continue;if(m.tiles[i]===0)wallTile(x,y,s.visible[i]);else if(m.tiles[i]===2){ctx.save();ctx.globalAlpha=s.visible[i]?1:.3;drawDoor(x,y);ctx.restore();}else if(m.tiles[i]===3){ctx.save();ctx.globalAlpha=s.visible[i]?1:.3;drawStairs(x,y);ctx.restore();}}
 for(const h of m.hazards)if(s.explored[h.y*m.w+h.x]){ctx.save();ctx.globalAlpha=s.visible[h.y*m.w+h.x]?1:.3;drawHazard(h,time);ctx.restore();}
 for(const c of m.chests)if(s.explored[c.y*m.w+c.x]){ctx.save();ctx.globalAlpha=s.visible[c.y*m.w+c.x]?1:.3;drawChest(c);ctx.restore();}
 for(const l of m.loot)if(s.visible[l.y*m.w+l.x]){const p=screen(l.x,l.y);ctx.save();ctx.fillStyle='#e0bd68';ctx.strokeStyle='#968351';ctx.lineWidth=1;if(l.type==='key'){ctx.beginPath();ctx.arc(p.x-4,p.y-2,3,0,7);ctx.stroke();ctx.beginPath();ctx.moveTo(p.x-1,p.y);ctx.lineTo(p.x+6,p.y+6);ctx.lineTo(p.x+7,p.y+3);ctx.stroke();}else{for(let i=0;i<3;i++){ctx.beginPath();ctx.ellipse(p.x+(i-1)*4,p.y+i%2*3,3,2,0,0,7);ctx.fill();}}ctx.restore();}
 // Warm lanterns illuminate masonry. Flicker never touches simulation RNG.
 for(let y=minY;y<=maxY;y++)for(let x=minX;x<=maxX;x++)if(s.visible[y*m.w+x]&&m.tiles[y*m.w+x]===0&&E.tile(m,x,y+1)>0&&(visualHash(x,y,54)>.91||(x===m.entry.x-3&&y===m.entry.y-5))){const p=screen(x,y);const pulse=settings.reduced?1:.94+Math.sin(time*.004+x)*.06;ctx.save();const g=ctx.createRadialGradient(p.x,p.y+10,2,p.x,p.y+10,view.cell*1.8);g.addColorStop(0,'#f0bc5b30');g.addColorStop(1,'#d78c2500');ctx.fillStyle=g;ctx.fillRect(p.x-view.cell*2,p.y-view.cell*2,view.cell*4,view.cell*4);ctx.fillStyle='#6a4f2e';ctx.fillRect(p.x-2,p.y-2,4,14);ctx.shadowBlur=15;ctx.shadowColor='#ecb254';polygon([[p.x-4,p.y+1],[p.x-2,p.y-8*pulse],[p.x+1,p.y-12*pulse],[p.x+4,p.y-4],[p.x+3,p.y+1]],'#e7b661');ctx.fillStyle='#ffe1a1';ctx.fillRect(p.x-1,p.y-5,2,6);ctx.restore();}
 const pp=screen(s.player.x,s.player.y);let light=ctx.createRadialGradient(pp.x,pp.y,0,pp.x,pp.y,view.cell*6);light.addColorStop(0,'#e0bc6220');light.addColorStop(.6,'#d3b44d08');light.addColorStop(1,'#13201300');ctx.fillStyle=light;ctx.fillRect(0,0,view.w,view.h);
 if(debugMode==='walkability'||debugMode==='fov'){for(let y=minY;y<=maxY;y++)for(let x=minX;x<=maxX;x++){const i=y*m.w+x;if(!s.explored[i])continue;const p=screen(x,y);ctx.fillStyle=debugMode==='fov'?(s.visible[i]?'#69cace20':'#67769c20'):m.tiles[i]===2?'#e7b45355':m.tiles[i]>0?'#8cc47f24':'#d96c6517';ctx.fillRect(p.x-view.cell/2+2,p.y-view.cell/2+2,view.cell-4,view.cell-4);}}
 for(const t of s.telegraphs){if(!s.visible[t.y*m.w+t.x])continue;ctx.save();ctx.strokeStyle='#e89470';ctx.fillStyle='#d56f353b';ctx.lineWidth=2;for(let n=-2;n<=2;n++)for(const [dx,dy]of [[n,0],[0,n]]){const p=screen(t.x+dx,t.y+dy);ctx.fillRect(p.x-view.cell*.45,p.y-view.cell*.45,view.cell*.9,view.cell*.9);ctx.strokeRect(p.x-view.cell*.4,p.y-view.cell*.4,view.cell*.8,view.cell*.8);}ctx.restore();}
 if(preview.length){ctx.save();ctx.strokeStyle='#d4cc8b90';ctx.setLineDash([3,5]);ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(pp.x,pp.y);for(const q of preview){const p=screen(q.x,q.y);ctx.lineTo(p.x,p.y);}ctx.stroke();ctx.setLineDash([]);for(const q of preview){const p=screen(q.x,q.y);ctx.fillStyle='#e6d294';ctx.beginPath();ctx.arc(p.x,p.y,2,0,7);ctx.fill();}ctx.restore();}
 if(debugMode==='paths')for(const e of visibleEnemies()){ctx.strokeStyle='#dbafcb99';ctx.beginPath();let p=screen(e.x,e.y);ctx.moveTo(p.x,p.y);for(const q of e.path){if(!s.visible[q.y*m.w+q.x])break;p=screen(q.x,q.y);ctx.lineTo(p.x,p.y);}ctx.stroke();}
 const entities=[...visibleEnemies().map(e=>({e,player:false})),{e:s.player,player:true}].sort((a,b)=>a.e.y-b.e.y);for(const ent of entities)drawEntity(ent.e,ent.player,time);
 for(const n of s.sounds)if(!s.visible[n.y*m.w+n.x]){const p=screen(n.x,n.y);ctx.strokeStyle='#a3b59880';ctx.beginPath();ctx.arc(p.x,p.y,12+(settings.reduced?0:Math.sin(time/300)*3),0,7);ctx.stroke();ctx.fillStyle='#c3cbaa';ctx.font='12px Georgia';ctx.fillText('?',p.x-3,p.y+4);}
 if(hover&&s.visible[hover.y*m.w+hover.x]){const p=screen(hover.x,hover.y),c=view.cell;ctx.strokeStyle=selected==='move'||inspect?'#e6d5a1':'#e9ad78';ctx.lineWidth=1.5;ctx.fillStyle='#ddc88b0d';ctx.fillRect(p.x-c/2,p.y-c/2,c,c);const d=c*.2;for(const [ax,ay]of [[-1,-1],[1,-1],[-1,1],[1,1]]){ctx.beginPath();ctx.moveTo(p.x+ax*c*.45,p.y+ay*(c*.45-d));ctx.lineTo(p.x+ax*c*.45,p.y+ay*c*.45);ctx.lineTo(p.x+ax*(c*.45-d),p.y+ay*c*.45);ctx.stroke();}}
 effects=effects.filter(e=>time-e.born<700);for(const e of effects){if(!s.visible[e.y*m.w+e.x])continue;const p=screen(e.x,e.y),age=(time-e.born)/700;ctx.save();ctx.globalAlpha=1-age;if(e.text){ctx.font='bold 15px Georgia';ctx.textAlign='center';ctx.strokeStyle='#172114';ctx.lineWidth=3;const yy=p.y-22-(settings.reduced?0:age*20);ctx.strokeText(e.text,p.x,yy);ctx.fillStyle=e.color||'#efce93';ctx.fillText(e.text,p.x,yy);}if(e.type==='arrow'&&e.to){const q=screen(e.to.x,e.to.y),f=Math.min(1,age*4);ctx.strokeStyle='#ecdba9';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(p.x+(q.x-p.x)*Math.max(0,f-.12),p.y+(q.y-p.y)*Math.max(0,f-.12));ctx.lineTo(p.x+(q.x-p.x)*f,p.y+(q.y-p.y)*f);ctx.stroke();}if(e.type==='blast'){ctx.strokeStyle='#eeb16a';ctx.lineWidth=2;ctx.beginPath();ctx.arc(p.x,p.y,8+age*view.cell,0,7);ctx.stroke();}if(!settings.reduced&&(e.type==='hit'||e.type==='blast'))for(let i=0;i<6;i++){const a=i*1.2;ctx.fillStyle='#e3b678';ctx.fillRect(p.x+Math.cos(a)*age*30,p.y+Math.sin(a)*age*25,2,2);}ctx.restore();}
 if(!settings.reduced){ctx.save();ctx.fillStyle='#b4b58040';for(let i=0;i<14;i++){const x=((i*137.7+Math.sin(time*.0002+i)*18)%view.w+view.w)%view.w,y=((i*77.1-time*.003*(1+i%3))%view.h+view.h)%view.h;ctx.fillRect(x,y,1,1);}ctx.restore();}
 renderMini();frames++;if(time-lastFps>=1000){fps=Math.round(frames*1000/(time-lastFps));frames=0;lastFps=time;$('fpsLabel').textContent=fps;}requestAnimationFrame(render);
}
function renderMini(){const panel=document.querySelector('.minimap-wrap');if(view.w<500){const mw=panel.offsetWidth,mh=panel.offsetHeight,pad=9,positions=[{x:view.w-mw-pad,y:pad},{x:pad,y:pad},{x:view.w-mw-pad,y:view.h-mh-47},{x:pad,y:view.h-mh-47}],actors=[...visibleEnemies(),state.player];let best=positions[0],bestScore=Infinity;for(const pos of positions){let score=0;for(const actor of actors){const p=screen(actor.x,actor.y),margin=view.cell*.65;if(p.x>pos.x-margin&&p.x<pos.x+mw+margin&&p.y>pos.y-margin&&p.y<pos.y+mh+margin)score+=actor===state.player?100:20;}if(pos.x===pad&&pos.y===pad&&$('inspection').innerHTML)score+=80;if(score<bestScore){best=pos;bestScore=score;}}panel.style.left=best.x+'px';panel.style.right='auto';panel.style.top=best.y+'px';}else{panel.style.left='auto';panel.style.right='14px';panel.style.top='14px';}const m=state.map,w=230,h=162,c=Math.min((w-8)/m.w,(h-8)/m.h),ox=(w-m.w*c)/2,oy=(h-m.h*c)/2;mini.clearRect(0,0,w,h);mini.fillStyle='#0f160f';mini.fillRect(0,0,w,h);for(let y=0;y<m.h;y++)for(let x=0;x<m.w;x++){const i=y*m.w+x;if(!state.explored[i]||m.tiles[i]===0)continue;mini.fillStyle=m.tiles[i]===3?'#d8c581':m.tiles[i]===2?'#9c8250':state.visible[i]?'#78805a':'#38492f';mini.fillRect(ox+x*c,oy+y*c,c-.7,c-.7);}for(const e of visibleEnemies()){mini.fillStyle='#cf977b';mini.fillRect(ox+e.x*c,oy+e.y*c,c,c);}mini.fillStyle='#f2dda1';mini.shadowBlur=5;mini.shadowColor='#e5d48d';mini.fillRect(ox+state.player.x*c-1,oy+state.player.y*c-1,c+1,c+1);mini.shadowBlur=0;}
function showInspection(p){if(!p||!state.explored[p.y*state.map.w+p.x]){$('inspection').innerHTML=inspect?'<h3>Uncharted darkness</h3><p>Your lantern has not reached this tile.</p>':'';return;}const visible=state.visible[p.y*state.map.w+p.x],enemy=visible&&state.enemies.find(e=>e.x===p.x&&e.y===p.y),chest=state.map.chests.find(c=>c.x===p.x&&c.y===p.y),hazard=state.map.hazards.find(h=>h.x===p.x&&h.y===p.y);let title='',text='';if(enemy){const t=E.TYPES[enemy.type];title=t.name;text=enemy.hp+'/'+enemy.maxHp+' HP · '+enemy.atk+' attack · '+enemy.armor+' armor<br>Range '+t.range+' · guaranteed hit in reach.<br>'+t.desc+'<br><span class="gold">'+esc(enemy.intent)+'</span>';}else if(p.x===state.player.x&&p.y===state.player.y){title='Your lantern';text='Attack '+E.attackValue(state)+' · armor '+E.armorValue(state)+'<br>Move or attack: 1 turn. The world waits until you act.';}else if(chest){title=chest.opened?'Empty cache':chest.locked?'Sealed cache':'Supply cache';text=chest.opened?'The useful things are in your satchel.':'Stand on or beside it and interact. '+(chest.locked?'Requires 1 brass key. ':'')+'Gold, a draught, and a relic. Costs 1 turn.';}else if(hazard){title=(hazard.active?'Active ':'Disarmed ')+hazard.type+' trap';text=hazard.type==='spikes'?'5 armor-piercing damage once.':hazard.type==='poison'?'Poison: 2 damage per turn for up to 3 turns.':'Burning: 3 damage per turn for up to 3 turns.';text+='<br>Interact from an adjacent tile to disarm. 1 turn.';}else{const t=E.tile(state.map,p.x,p.y);title=t===0?'Ancient masonry':t===2?'Heavy door':t===3?(state.floor===3?'The Emberheart':'Stairs into the dark'):'Worn flagstone';text=t===0?'Solid stone. Blocks movement and line of sight.':t===2?'Blocks movement and vision. Bump or interact to open: 1 turn.':t===3?'Stand here and interact. '+(state.floor===3?'Defeat the Ash Warden to claim victory.':'Descend one floor: 1 turn; recover 8 HP and a draught.'):'Walkable ground. Move 1 tile per turn.';}if(!visible)text='Explored, currently unseen. Last known terrain.<br>'+text;$('inspection').innerHTML='<div class="eyebrow" style="font-size:7px;margin-bottom:5px">'+p.x+', '+p.y+' · '+(visible?'IN SIGHT':'REMEMBERED')+'</div><h3>'+esc(title)+'</h3><p>'+text+'</p>';}
function safePath(to){const blocked=new Set(state.enemies.filter(e=>state.visible[e.y*state.map.w+e.x]).map(e=>E.key(e.x,e.y)));return E.path(state.map,state.player,to,blocked,(x,y)=>state.visible[y*state.map.w+x]&&!state.map.hazards.some(h=>h.active&&h.x===x&&h.y===y),false);}
function walkPreview(){if(!preview.length||!canPlay())return;const next=preview.shift();if(!state.visible[next.y*state.map.w+next.x]||!E.walk(state.map,next.x,next.y)||state.enemies.some(e=>e.x===next.x&&e.y===next.y)||state.map.hazards.some(h=>h.active&&h.x===next.x&&h.y===next.y)){stopWalk();mapToast('Route stopped: the way is no longer safe.');return;}const danger=visibleEnemies().length;if(danger&&preview.length){stopWalk();mapToast('Threats nearby. Choose one step at a time.');return;}const hp=state.player.hp,ok=perform({type:'move',dx:next.x-state.player.x,dy:next.y-state.player.y},true);if(!ok||state.player.hp<hp||visibleEnemies().length>danger){stopWalk();return;}if(preview.length)walkTimer=setTimeout(walkPreview,Math.max(120,settings.speed+35));else previewTarget=null;}
canvas.addEventListener('pointermove',ev=>{hover=tileFromPointer(ev);if(inspect||state.enemies.some(e=>e.x===hover.x&&e.y===hover.y&&state.visible[e.y*state.map.w+e.x]))showInspection(hover);else $('inspection').innerHTML='';});canvas.addEventListener('pointerleave',()=>{if(!inspect){hover=null;$('inspection').innerHTML='';}});
canvas.addEventListener('pointerdown',ev=>{if(ev.button!==0)return;canvas.focus({preventScroll:true});const q=tileFromPointer(ev);hover=q;if(inspect){showInspection(q);return;}if(!canPlay())return;if(!state.visible[q.y*state.map.w+q.x]){mapToast('Only visible tiles can be targeted.');return;}if(selected!=='move'){const ok=selected==='shot'?perform({type:'shot',...q}):perform({type:'item',item:selected,...q});if(ok){selected='move';renderUI();}return;}if(q.x===state.player.x&&q.y===state.player.y){perform({type:'interact'});return;}const enemy=state.enemies.find(e=>e.x===q.x&&e.y===q.y);if(E.dist(q,state.player)===1){perform({type:'move',dx:q.x-state.player.x,dy:q.y-state.player.y});return;}if(enemy){showInspection(q);mapToast('Use the longbow, or close to melee range.');return;}if(previewTarget&&q.x===previewTarget.x&&q.y===previewTarget.y){walkPreview();return;}const route=safePath(q);if(!route.length){mapToast('No safe visible route. Move closer or open the door.');return;}preview=route;previewTarget=q;mapToast(route.length+' steps · click again to walk'+(visibleEnemies().length?' · threats stop travel':''));});
function openModal(name,title,body,eyebrow='EXPEDITION PAUSED'){stopWalk();lastFocus=document.activeElement;paused=true;modalName=name;$('modalEyebrow').textContent=eyebrow;$('modalTitle').textContent=title;$('modalBody').innerHTML=body;$('modalBackdrop').hidden=false;renderUI();setTimeout(()=>$('closeModal').focus({preventScroll:true}),0);}
function closeModal(){if(replayInfo&&modalName==='replay'){stopReplay();return;}modalName='';$('modalBackdrop').hidden=true;paused=false;renderUI();(lastFocus&&lastFocus.isConnected?lastFocus:canvas).focus({preventScroll:true});}
function openMenu(){if(replayInfo){openModal('replayMenu','The story is paused','<p>Playback is paused at action '+replayInfo.index+' of '+replayInfo.actions.length+'. Your original expedition is preserved.</p><div class="modal-actions"><button class="primary" data-command="resume">Resume replay</button><button data-command="stopReplay">Stop replay & return</button></div>');return;}openModal('menu','A moment by the lantern','<p>The dungeon is still. Plan your next move.</p><div class="row"><button class="primary" data-command="resume">Resume expedition</button><button data-command="save">Save run</button><button data-command="load">Load saved run</button></div><h3>Your expedition</h3><div class="row"><button data-command="new">New expedition</button><button data-command="restart" '+(state.config.mode==='permadeath'?'disabled':'')+'>Restart this floor</button><button data-command="replay">Replay actions</button></div><h3>Make yourself at home</h3><div class="row"><button data-command="settings">Settings</button><button data-command="help">Keyboard & rules</button><button data-command="diagnostics">Diagnostics</button></div><h3>Carry the story with you</h3><div class="row"><button data-command="export">Export run JSON</button><button data-command="import">Import run JSON</button><button data-command="records">Local chronicle</button></div><p class="tiny" style="margin-top:18px;margin-bottom:0">'+esc(state.config.seed)+' · '+esc(state.config.difficulty)+' · '+esc(state.config.mode)+'<br>Turn '+state.turn+' · fingerprint '+E.fingerprint(state)+'</p>');}
function openNew(){let hero=state.config.hero;openModal('new','Every descent is a new story','<p>Three floors. One Emberheart. Choose what you carry into the dark.</p><div class="class-choices">'+['warden','ranger','alchemist'].map(h=>'<button class="class-choice '+(h===hero?'selected':'')+'" data-hero="'+h+'" aria-pressed="'+(h===hero)+'">'+portrait(h)+'<strong>'+{warden:'Warden',ranger:'Ranger',alchemist:'Alchemist'}[h]+'</strong><small>'+{warden:'36 HP · 7 attack · 2 armor<br>A steady blade and stout armor.',ranger:'30 HP · 6 attack · 1 armor<br>Longbow deals 9 damage.',alchemist:'29 HP · 5 attack · 1 armor<br>Extra flasks. Stronger fire.'}[h]+'</small></button>').join('')+'</div><div class="form-grid"><label class="field full">World seed<div class="row"><input id="newSeed" value="'+esc(state.config.seed)+'" maxlength="80" style="flex:1;min-width:0" aria-label="World seed"><button id="dailyButton" type="button" title="UTC date, no network needed">Daily seed</button></div><small>The same seed, style, and loadout create the same expedition.</small></label><label class="field">Dungeon style<select id="newStyle"><option value="ruins">Overgrown ruins</option><option value="cavern">Caverns</option><option value="fortress">Fortress</option><option value="crypt">Crypt</option><option value="arena">Compact test arena</option></select></label><label class="field">Difficulty<select id="newDifficulty"><option value="normal">Wayfarer · Normal</option><option value="story">Story · +14 HP, gentler foes</option><option value="veteran">Veteran · +25% incoming damage</option></select></label><label class="field">Run mode<select id="newMode"><option value="forgiving">Forgiving · Floor checkpoints</option><option value="permadeath">Permadeath · One lantern</option></select></label><label class="field">Starting point<select id="newPreset"><option value="standard">Full expedition · Floor 1</option><option value="final">Final encounter · Floor 3</option></select></label></div><div class="error-box" id="newError"></div><div class="modal-actions"><button data-command="resume">Back to expedition</button><button class="primary" id="beginRun">Light the lantern →</button></div>','EVERY SEED, A NEW WORLD');$('newStyle').value=state.config.style;$('newDifficulty').value=state.config.difficulty;$('newMode').value=state.config.mode;$('modalBody').querySelectorAll('[data-hero]').forEach(b=>b.onclick=()=>{hero=b.dataset.hero;document.querySelectorAll('[data-hero]').forEach(btn=>{btn.classList.toggle('selected',btn.dataset.hero===hero);btn.setAttribute('aria-pressed',btn.dataset.hero===hero);});});$('dailyButton').onclick=()=>{$('newSeed').value='DAILY-'+new Date().toISOString().slice(0,10);};$('beginRun').onclick=()=>{const seed=$('newSeed').value.trim();if(!seed){$('newError').textContent='Give your world a seed before you descend.';return;}state=E.create({seed,hero,style:$('newStyle').value,difficulty:$('newDifficulty').value,mode:$('newMode').value,preset:$('newPreset').value});recorded=false;oldPositions={};effects=[];selected='move';inspect=false;hover=null;$('inspection').innerHTML='';closeModal();save();renderUI();canvas.focus({preventScroll:true});mapToast('Your lantern is lit. The descent begins.');tone('heal');};}
function openInventory(){const p=state.player;openModal('inventory','Your travelling satchel','<p>Browsing is free. Using an item or changing equipment takes one turn and lets enemies act.</p><h3>Equipped</h3><div class="inventory-grid">'+Object.entries(p.gear).map(([slot,id])=>'<div class="item-card equipped">'+icon(slot==='weapon'?'sword':slot==='armor'?'mail':'charm')+'<span><strong>'+esc(id?E.GEAR[id].name:'Empty talisman slot')+'</strong><small>'+slot.toUpperCase()+(id?' · '+esc(E.GEAR[id].desc):'')+'</small></span></div>').join('')+'</div><h3>Provisions & relics</h3><div class="inventory-grid">'+Object.entries(E.ITEMS).map(([id,item])=>'<button class="item-card" data-use="'+id+'" '+(p.items[id]===0||id==='key'?'disabled':'')+'>'+icon(item.icon)+'<span><strong>'+item.name+' <span class="gold">×'+p.items[id]+'</span></strong><small>'+item.desc+'</small></span></button>').join('')+'</div><h3>Equipment</h3><div class="inventory-grid">'+p.bag.map(id=>{const g=E.GEAR[id],equipped=p.gear[g.slot]===id;return'<button class="item-card '+(equipped?'equipped':'')+'" data-equip="'+id+'" '+(equipped?'disabled':'')+'>'+icon(g.slot==='weapon'?'sword':g.slot==='armor'?'mail':'charm')+'<span><strong>'+g.name+(equipped?' · equipped':'')+'</strong><small>'+g.desc+'</small></span></button>';}).join('')+'</div>');$('modalBody').querySelectorAll('[data-use]').forEach(b=>b.onclick=()=>{const id=b.dataset.use;closeModal();if(['fire','frost','blink'].includes(id))selectAction(id);else perform({type:'item',item:id});canvas.focus({preventScroll:true});});$('modalBody').querySelectorAll('[data-equip]').forEach(b=>b.onclick=()=>{const id=b.dataset.equip;closeModal();perform({type:'equip',id});canvas.focus({preventScroll:true});});}
function openSettings(){openModal('settings','Tune your descent','<div class="form-grid"><label class="field">Animation speed<select id="animationSetting"><option value="0">Instant</option><option value="90">Swift · 90 ms</option><option value="150">Normal · 150 ms</option><option value="300">Deliberate · 300 ms</option></select></label><label class="field">Text size<select id="textSetting"><option value="14">Standard</option><option value="16">Comfortable</option><option value="18">Large</option></select></label><label class="field">Alternate movement<select id="keysSetting"><option value="wasd">WASD + arrow keys</option><option value="vi">Vi HJKL + arrow keys</option></select></label><label class="field">Master volume <span id="volumeLabel">'+Math.round(settings.volume*100)+'%</span><input type="range" id="volumeSetting" min="0" max="100" value="'+Math.round(settings.volume*100)+'"></label></div><div style="margin-top:16px"><label class="toggle-row"><span>Reduced motion<small>Instant movement; no floating particles or flicker.</small></span><input id="motionSetting" type="checkbox" '+(settings.reduced?'checked':'')+'></label><label class="toggle-row"><span>High contrast<small>Brighter text, borders, and interface accents.</small></span><input id="contrastSetting" type="checkbox" '+(settings.contrast?'checked':'')+'></label><label class="toggle-row"><span>Procedural sound<small>Soft synthesized steps, strikes, and restorative chimes.</small></span><input id="soundSetting" type="checkbox" '+(settings.sound?'checked':'')+'></label><label class="toggle-row"><span>Save after every turn<small>Restore this exact expedition when you return.</small></span><input id="autosaveSetting" type="checkbox" '+(settings.autosave?'checked':'')+'></label></div><div class="modal-actions"><button class="primary" data-command="resume">Return to expedition</button></div>');$('animationSetting').value=String(settings.speed);$('textSetting').value=String(settings.text);$('keysSetting').value=settings.keys;for(const [id,name,kind]of [['animationSetting','speed','number'],['textSetting','text','number'],['keysSetting','keys','text'],['motionSetting','reduced','check'],['contrastSetting','contrast','check'],['soundSetting','sound','check'],['autosaveSetting','autosave','check']])$(id).onchange=()=>{settings[name]=kind==='check'?$(id).checked:kind==='number'?Number($(id).value):$(id).value;if(name==='sound'&&settings.sound){enableAudio();tone('heal');}applySettings();};$('volumeSetting').oninput=()=>{settings.volume=Number($('volumeSetting').value)/100;$('volumeLabel').textContent=Math.round(settings.volume*100)+'%';applySettings();};}
function openHelp(){openModal('help','A little knowledge. A longer life.','<p>One accepted action advances the world exactly once. Invalid targets, blocked moves, inspection, menus, saves, and cancelling a target cost no turns. Auto-travel stops on new threats, damage, and blockage.</p><div class="rules">'+[['Move / bump melee','↑ ↓ ← → · WASD'],['Alternate movement','H J K L · Settings'],['Blade / bow / draught','1 / 2 / 3'],['Cycle / use target','Tab / Enter'],['Flask / frost / brace','4 / 5 / 6'],['Wait one turn','. or Space'],['Open / disarm / descend','E or Enter'],['Close adjacent doorway','C'],['Inventory','I'],['Inspect without acting','X'],['Pause / cancel targeting','Esc or P'],['Cycle live diagnostics','`'],['This guide','?']].map(([label,k])=>'<div class="rule"><span>'+label+'</span><kbd>'+k+'</kbd></div>').join('')+'</div><h3>The rhythm of a turn</h3><p>Your action → traps and marked attacks → ongoing poison / burning → one action per living enemy → status and cooldown timers. Descending consumes one turn and protects your new entry. Every enemy attack must have line of sight. Memory fades after four unseen turns.</p><h3>Combat, made readable</h3><p>Melee and ranged hits are guaranteed when valid. Damage = attack − armor, minimum 1. Melee has a seeded 15% critical chance for +50% base damage. Brace adds 4 armor for 3 enemy phases. Longbow recovery is 2 turns. Experience raises attack and vitality and restores 12 HP. Difficulty scales incoming damage before armor: Story ×0.7, Normal ×1, Veteran ×1.25, rounded to a whole number.</p><h3>Pointer & touch</h3><p>Tap an adjacent tile to step or attack. Tap a distant visible safe tile to preview a path, then tap it again to walk. Travel stops near threats. Select a ranged action, then tap its target. Touch arrows stay below the action bar.</p><div class="modal-actions"><button data-command="settings">Key layout & accessibility</button><button class="primary" data-command="resume">I’m ready</button></div>');}
function openCodex(){openModal('codex','The wayfarer’s field guide','<p>The Emberheart lies three floors below. Bring it back, if you can. Nothing in this world moves until you do.</p><h3>Know what waits</h3><div class="legend-grid">'+Object.values(E.TYPES).map(t=>'<div><strong>'+t.name+'</strong>'+t.desc+'<br><span class="gold">'+t.hp+' base HP · '+t.atk+' attack · '+t.armor+' armor</span></div>').join('')+'</div><h3>A world grown from a seed</h3><p>Overgrown ruins, open caverns, fortified corridors, and pillared crypts are connected by reachable passages. Every descent changes the style. The compact arena is useful for a shorter tactical trial. The final-encounter preset begins on floor three with upgraded equipment.</p><h3>Keep your light</h3><p>Supply caches provide gold and consumables. Sealed caches require a brass key. Interact beside traps to disarm them. Explore around blind corners: doors and masonry block sight. Listen for creaking doors beyond your lantern.</p><div class="modal-actions"><button data-command="help">Controls & turn rules</button><button class="primary" data-command="resume">Back to the vault</button></div>','NOTES FROM THOSE WHO RETURNED');}
function getRecords(){try{const r=JSON.parse(localStorage.getItem(RECORD_KEY)||'[]');return Array.isArray(r)?r.filter(x=>x&&typeof x.seed==='string'&&Number.isFinite(x.score)).slice(0,20):[];}catch{return[];}}
function storeRecord(){if(recorded||replayInfo)return;recorded=true;try{let r=getRecords();const rec={seed:state.config.seed,hero:state.config.hero,outcome:state.outcome,floor:state.floor,turn:state.turn,score:E.score(state),date:new Date().toISOString().slice(0,10),fingerprint:E.fingerprint(state),preset:state.config.preset};if(!r.some(a=>a.fingerprint===rec.fingerprint))r.push(rec);r.sort((a,b)=>b.score-a.score);localStorage.setItem(RECORD_KEY,JSON.stringify(r.slice(0,20)));}catch{notify('Local records unavailable; export this run to keep it.');}}
function openRecords(){const records=getRecords();openModal('records','The lantern chronicle','<p>Stories kept on this device. Your best twenty expeditions.</p>'+(records.length?records.map((r,i)=>'<div class="record"><div><span class="muted">'+String(i+1).padStart(2,'0')+' · </span><b>'+esc(r.seed)+'</b><div class="tiny muted">'+esc(r.hero)+' · '+esc(r.outcome)+' · F'+r.floor+' · '+r.turn+' turns'+(r.preset==='final'?' · final preset':'')+'</div></div><div class="gold mono">'+r.score+'<div class="tiny muted">'+esc(r.date)+'</div></div></div>').join(''):'<div class="result-hero"><div class="sigil">◇</div><h3>Your story is still being written.</h3><p>Complete an expedition to leave a mark here.</p></div>')+'<div class="modal-actions"><button class="primary" data-command="resume">Return to expedition</button></div>','EVERY DESCENT LEAVES A TRACE');}
function showResult(){if(replayInfo)return;const victory=state.outcome==='victory';openModal('result',victory?'A light brought home':'The vault remembers','<div class="result-hero"><div class="sigil">'+(victory?'✧':'◇')+'</div><h3>'+(victory?'You recovered the Emberheart.':'Your lantern has gone dark.')+'</h3><p>'+(victory?'The Ash Warden is silent. For the first time in an age, dawn touches the roots.':'The passages fall quiet. Somewhere below, the heart is still burning.')+'</p></div><div class="result-numbers"><div><b>'+E.score(state)+'</b><span>SCORE</span></div><div><b>'+state.turn+'</b><span>TURNS</span></div><div><b>'+state.player.kills+'</b><span>FOES FELLED</span></div></div><p class="mono tiny" style="text-align:center">'+esc(state.config.seed)+' · FLOOR '+state.floor+' · LEVEL '+state.player.level+'</p><div class="modal-actions">'+(!victory&&state.config.mode==='forgiving'?'<button data-command="restart">Retry this floor</button>':'')+'<button data-command="replay">Replay this story</button><button class="primary" data-command="new">A new descent →</button></div>','EXPEDITION '+(victory?'COMPLETE':'ENDED'));if(victory)tone('victory');}
function restartFloor(){if(state.config.mode==='permadeath'){notify('Permadeath has no floor retries. Begin a new expedition.');return;}if(!state.checkpoint){notify('This save has no floor checkpoint.');return;}openModal('restart','Relight at this floor’s entrance','<p>Return to the turn you entered floor '+state.floor+'. This replaces progress made on this floor, including inventory changes and combat. Your earlier floors remain in the action history.</p><div class="modal-actions"><button data-command="resume">Keep going</button><button class="primary" id="confirmRestart">Relight the lantern</button></div>');$('confirmRestart').onclick=()=>{const c=E.clone(state.checkpoint);state=c;state.checkpoint=E.clone(c);recorded=false;oldPositions={};effects=[];hover=null;selected='move';closeModal();save();renderUI();notify('Restored the entrance checkpoint at turn '+state.turn+'.');};}
function openImport(){openModal('import','Bring a story back','<p>Import a complete Embervault v3 run. Invalid or older files leave your current expedition intact.</p><label class="field">Choose a run JSON file<input id="importFile" type="file" accept=".json,application/json"></label><label class="field" style="margin-top:15px">Or paste run JSON<textarea id="importText" rows="6" spellcheck="false" placeholder="Paste your exported run here"></textarea></label><div class="error-box" id="importError"></div><div class="modal-actions"><button data-command="resume">Cancel</button><button class="primary" id="confirmImport">Restore expedition</button></div>');$('importFile').onchange=async()=>{const f=$('importFile').files[0];if(!f)return;if(f.size>8000000){$('importError').textContent='This file is too large (maximum 8 MB).';return;}$('importText').value=await f.text();};$('confirmImport').onclick=()=>{const d=E.decode($('importText').value);if(!d.ok){$('importError').textContent=d.error;return;}state=d.state;oldPositions={};effects=[];selected='move';inspect=false;hover=null;recorded=false;closeModal();save();renderUI();notify('Expedition restored exactly at turn '+state.turn+'.');};}
function exportRun(){const blob=new Blob([E.encode(state)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='embervault-'+state.config.seed.replace(/[^a-z0-9_-]/gi,'_')+'-t'+state.turn+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);notify('Run exported with complete state and deterministic action history.');}
function loadRun(){try{const raw=localStorage.getItem(SAVE_KEY);if(!raw){notify('No saved expedition yet. Save or import a run.');return;}const d=E.decode(raw);if(!d.ok){notify(d.error);return;}state=d.state;oldPositions={};effects=[];selected='move';hover=null;closeModal();renderUI();notify('Exact state loaded at turn '+state.turn+'.');}catch{notify('Browser storage is unavailable. Use JSON import.');}}
function openDiagnostics(){openModal('diagnostics','Look under the flagstones','<p>These overlays read the live simulation. Hidden enemies stay hidden on the battlefield; the console includes aggregate occupancy and queue data.</p><label class="field">Diagnostic overlay<select id="debugSelect">'+['off','validation','fov','walkability','paths','occupancy','queue'].map(d=>'<option value="'+d+'">'+{off:'Off',validation:'Generation, connectivity & random state',fov:'Field of view & explored memory',walkability:'Walkability & doors',paths:'Enemy paths, intent & memory',occupancy:'Collision occupancy',queue:'Last turn queue'}[d]+'</option>').join('')+'</select></label><div class="modal-actions"><button id="validateFloors">Validate this seed · all floors</button><button class="primary" data-command="resume">Return to expedition</button></div><pre id="generationResult" style="white-space:pre-wrap;font:11px/1.7 monospace;color:#b9cda4;margin-top:18px"></pre>');$('debugSelect').value=debugMode;$('debugSelect').onchange=()=>{debugMode=$('debugSelect').value;updateDebug();};$('validateFloors').onclick=()=>{const lines=[];for(let f=1;f<=3;f++){const m=E.generate(state.config.seed,f,E.floorStyle(state,f)),v=E.validateMap(m);lines.push('Floor '+f+' · '+(v.valid?'PASS':'FAIL')+' · '+v.reachable+'/'+v.total+' connected tiles · exit '+v.exitDistance+' steps');}$('generationResult').textContent=lines.join('\n');};}
function startReplay(){if(replayInfo){notify('A replay is already running. Stop it to return to your expedition.');return;}clearTimeout(replayTimer);if(!state.history.length){notify('Take a few turns first to build an action history.');return;}const original=E.clone(state),actions=E.clone(state.history),expected=E.fingerprint(state);closeModal();state=E.create(original.config);replayInfo={original,actions,index:0,expected};paused=false;selected='move';effects=[];oldPositions={};renderUI();notify('Replaying the original seed and actions. Escape stops.');function step(){if(!replayInfo)return;if(paused){replayTimer=setTimeout(step,100);return;}if(replayInfo.index<actions.length){const result=E.act(state,actions[replayInfo.index]);if(!result.ok){const index=replayInfo.index;stopReplay();notify('Replay diverged at action '+index+'.');return;}replayInfo.index++;renderUI();replayTimer=setTimeout(step,Math.max(45,settings.speed));}else{const actual=E.fingerprint(state),ok=actual===expected;openModal('replay',ok?'Every step, remembered':'Replay verification failed','<div class="result-hero"><div class="sigil">'+(ok?'✧':'!')+'</div><h3>'+(ok?'Deterministic replay verified.':'The state does not match.')+'</h3><p>'+actions.length+' actions re-simulated from seed <b>'+esc(state.config.seed)+'</b>.<br>Original '+expected+' · replay '+actual+'</p></div><div class="modal-actions"><button class="primary" data-command="stopReplay">Return to your expedition</button></div>','ACTION HISTORY · RE-SIMULATION');}}replayTimer=setTimeout(step,150);}
function stopReplay(){if(replayInfo){clearTimeout(replayTimer);state=replayInfo.original;replayInfo=null;}modalName='';paused=false;$('modalBackdrop').hidden=true;effects=[];oldPositions={};renderUI();canvas.focus({preventScroll:true});}
function command(cmd){if(replayInfo&&['new','load','import','restart','save','export','replay','inventory','interact'].includes(cmd)){notify('Stop the replay to return to your expedition first.');return;}switch(cmd){case'expedition':if(modalName)closeModal();break;case'menu':openMenu();break;case'resume':closeModal();break;case'new':openNew();break;case'inventory':openInventory();break;case'help':openHelp();break;case'codex':openCodex();break;case'settings':openSettings();break;case'records':openRecords();break;case'save':save(true);renderUI();break;case'load':loadRun();break;case'restart':restartFloor();break;case'export':exportRun();break;case'import':openImport();break;case'replay':startReplay();break;case'stopReplay':stopReplay();break;case'debug':cycleDebug();break;case'diagnostics':openDiagnostics();break;case'inspect':if(!modalName){inspect=!inspect;selected='move';stopWalk();$('inspection').innerHTML='';renderUI();if(inspect)mapToast('Inspect mode · hover or tap a tile');}break;case'interact':perform({type:'interact'});break;case'log':openModal('log','A journal of the descent','<p>Each number is the simulation turn. The latest 250 events are kept in your save.</p><div style="max-height:55vh;overflow:auto">'+state.log.slice().reverse().map(logHTML).join('')+'</div>');break;}}
document.addEventListener('pointerdown',()=>{if(settings.sound&&(!audioCtx||audioCtx.state!=='running'))enableAudio();},{capture:true});
document.addEventListener('keydown',()=>{if(settings.sound&&(!audioCtx||audioCtx.state!=='running'))enableAudio();},{capture:true});
document.addEventListener('click',ev=>{const b=ev.target.closest('button');if(!b||b.disabled)return;if(b.dataset.command)command(b.dataset.command);else if(b.dataset.action)selectAction(b.dataset.action);else if(b.dataset.move){const [dx,dy]=b.dataset.move.split(',').map(Number);perform({type:'move',dx,dy});}});
$('closeModal').onclick=closeModal;$('modalBackdrop').addEventListener('pointerdown',ev=>{if(ev.target===$('modalBackdrop'))closeModal();});$('soundButton').onclick=()=>{settings.sound=!settings.sound;if(settings.sound){enableAudio();tone('heal');}applySettings();notify(settings.sound?'Sound enabled · volume '+Math.round(settings.volume*100)+'%':'Sound muted');};
document.addEventListener('keydown',ev=>{const inInput=['INPUT','TEXTAREA','SELECT'].includes(ev.target.tagName);if(ev.key==='Tab'&&modalName){const focusable=Array.from($('modalBackdrop').querySelectorAll('button:not(:disabled),input,select,textarea')).filter(e=>!e.hidden),first=focusable[0],last=focusable.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first.focus();}return;}if(ev.key==='Escape'){ev.preventDefault();if(replayInfo){stopReplay();return;}if(modalName){closeModal();return;}if(selected!=='move'||inspect||preview.length){selected='move';inspect=false;stopWalk();$('inspection').innerHTML='';renderUI();return;}openMenu();return;}if(inInput||ev.ctrlKey||ev.metaKey||ev.altKey)return;if(modalName)return;const k=ev.key.toLowerCase();if(k==='p'){ev.preventDefault();openMenu();return;}if(k==='i'){ev.preventDefault();openInventory();return;}if(k==='?'||k==='/'){ev.preventDefault();openHelp();return;}if(k==='x'){ev.preventDefault();command('inspect');return;}if(k==='`'){ev.preventDefault();cycleDebug();return;}if(!canPlay())return;if(k==='tab'&&selected!=='move'){ev.preventDefault();const list=visibleEnemies();if(list.length){const index=list.findIndex(e=>hover&&e.x===hover.x&&e.y===hover.y),e=list[(index+1)%list.length];hover={x:e.x,y:e.y};showInspection(hover);}return;}let moves={arrowup:[0,-1],arrowright:[1,0],arrowdown:[0,1],arrowleft:[-1,0]};Object.assign(moves,settings.keys==='vi'?{k:[0,-1],l:[1,0],j:[0,1],h:[-1,0]}:{w:[0,-1],d:[1,0],s:[0,1],a:[-1,0]});if(moves[k]){ev.preventDefault();if(ev.repeat&&performance.now()-animStart<Math.max(80,settings.speed))return;const [dx,dy]=moves[k];selected='move';inspect=false;$('inspection').innerHTML='';perform({type:'move',dx,dy});return;}if(k==='.'||k===' '){ev.preventDefault();if(ev.repeat)return;perform({type:'wait'});}else if(k==='e'||k==='enter'){ev.preventDefault();if(k==='enter'&&selected!=='move'&&hover){const ok=selected==='shot'?perform({type:'shot',...hover}):perform({type:'item',item:selected,...hover});if(ok){selected='move';renderUI();}return;}if(ev.target.closest('button'))return;perform({type:'interact'});}else if(k==='c'){ev.preventDefault();perform({type:'close'});}else if(/^[1-6]$/.test(k)){ev.preventDefault();selectAction(actions[Number(k)-1].id);}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&!modalName&&!replayInfo&&state.outcome==='active'){stopWalk();paused=true;renderUI();}else if(!document.hidden&&paused&&!modalName&&!replayInfo){openMenu();}});
window.addEventListener('resize',resize);new ResizeObserver(resize).observe($('mapWrap'));window.addEventListener('beforeunload',()=>{if(settings.autosave)save();});
// Read-only live diagnostics for inspectability; simulation commands remain the same user-facing engine.
window.Embervault={getState:()=>E.clone(state),getDiagnostics:()=>({fingerprint:E.fingerprint(state),map:E.validateMap(state.map),paused,modal:modalName,selected,inspect,debugMode,turn:state.turn,fps,visibleEnemies:visibleEnemies().map(e=>e.id),queue:[...state.queue],audio:{...audioStats,state:audioCtx?.state||'not created'},replay:replayInfo?{index:replayInfo.index,total:replayInfo.actions.length}:null,view:{...view}}),tileToScreen:(x,y)=>{const p=screen(x,y),r=canvas.getBoundingClientRect();return{x:p.x+r.left,y:p.y+r.top};}};
applySettings();renderUI();requestAnimationFrame(render);if(storageWarning)setTimeout(()=>notify(storageWarning),600);else if(state.turn>0)setTimeout(()=>notify('Welcome back. Your lantern waits at turn '+state.turn+'.'),500);if(state.outcome!=='active')setTimeout(showResult,600);
